using System.Linq.Expressions;
using FluentValidation;
using Microsoft.EntityFrameworkCore;
using Stockly.Application.Common;
using Stockly.Domain.Common;
using Stockly.Domain.Entities;
using Stockly.Domain.Enums;

namespace Stockly.Application.Features.Stock;

/// <summary>Manual movements. Sales (and their reversals) are generated by invoices, never by hand.</summary>
public enum ManualMovementType
{
    Entrada = StockMovementType.Entrada,
    Salida = StockMovementType.Salida,
    Ajuste = StockMovementType.Ajuste,
}

/// <param name="Quantity">Units for Entrada/Salida; the physically counted quantity for Ajuste.</param>
public sealed record StockMovementRequest(
    ManualMovementType Type, int ProductId, int WarehouseId, int Quantity, string? Reason, string? Reference, int? SupplierId);

public sealed record StockTransferRequest(int ProductId, int FromWarehouseId, int ToWarehouseId, int Quantity, string? Reason);

public sealed record StockMovementDto(
    int Id, DateTime CreatedAt, StockMovementType Type, int ProductId, string Sku, string ProductName,
    int WarehouseId, string WarehouseCode, int Quantity, int BalanceAfter, string? Reason, string? Reference,
    int? InvoiceId, string? SupplierName, string UserName, Guid CorrelationId);

public sealed record StockMovementQuery : PageRequest
{
    public int? ProductId { get; init; }
    public int? WarehouseId { get; init; }
    public StockMovementType? Type { get; init; }
    public DateOnly? From { get; init; }
    public DateOnly? To { get; init; }
}

public sealed class StockMovementRequestValidator : AbstractValidator<StockMovementRequest>
{
    public StockMovementRequestValidator()
    {
        RuleFor(x => x.Type).IsInEnum();
        RuleFor(x => x.ProductId).GreaterThan(0);
        RuleFor(x => x.WarehouseId).GreaterThan(0);
        RuleFor(x => x.Quantity).GreaterThan(0).When(x => x.Type != ManualMovementType.Ajuste);
        RuleFor(x => x.Quantity).GreaterThanOrEqualTo(0).When(x => x.Type == ManualMovementType.Ajuste)
            .WithMessage("La cantidad contada no puede ser negativa.");
        RuleFor(x => x.Quantity).LessThanOrEqualTo(1_000_000);
        RuleFor(x => x.Reason).NotEmpty().When(x => x.Type != ManualMovementType.Entrada)
            .WithMessage("Indicá el motivo de la salida o del ajuste.");
        RuleFor(x => x.Reason).MaximumLength(250);
        RuleFor(x => x.Reference).MaximumLength(60);
        RuleFor(x => x.SupplierId).Null().When(x => x.Type != ManualMovementType.Entrada)
            .WithMessage("El proveedor solo aplica a entradas.");
    }
}

public sealed class StockTransferRequestValidator : AbstractValidator<StockTransferRequest>
{
    public StockTransferRequestValidator()
    {
        RuleFor(x => x.ProductId).GreaterThan(0);
        RuleFor(x => x.FromWarehouseId).GreaterThan(0);
        RuleFor(x => x.ToWarehouseId).GreaterThan(0).NotEqual(x => x.FromWarehouseId)
            .WithMessage("El depósito de destino debe ser distinto al de origen.");
        RuleFor(x => x.Quantity).GreaterThan(0).LessThanOrEqualTo(1_000_000);
        RuleFor(x => x.Reason).MaximumLength(250);
    }
}

public sealed class StockService(IAppDbContext db, IStockStore store, IBusinessClock clock, ICurrentUser currentUser)
{
    private static readonly SortMap<StockMovement> Sorts = new SortMap<StockMovement>("createdAt", defaultDescending: true)
        .Add("createdAt", m => m.Id)
        .Add("product", m => m.Product.Name)
        .Add("warehouse", m => m.Warehouse.Code)
        .Add("type", m => m.Type)
        .Add("quantity", m => m.Quantity);

    private static readonly Expression<Func<StockMovement, StockMovementDto>> ToDto = m => new StockMovementDto(
        m.Id, m.CreatedAt, m.Type, m.ProductId, m.Product.Sku, m.Product.Name, m.WarehouseId, m.Warehouse.Code,
        m.Quantity, m.BalanceAfter, m.Reason, m.Reference, m.InvoiceId, m.Supplier != null ? m.Supplier.Name : null,
        m.User.FullName, m.CorrelationId);

    public Task<PagedResult<StockMovementDto>> SearchAsync(StockMovementQuery query, CancellationToken ct) =>
        Sorts.Apply(Filter(query), query.Sort).ToPagedAsync(query, ToDto, ct);

    public async Task<byte[]> ExportCsvAsync(StockMovementQuery query, CancellationToken ct)
    {
        var rows = await Sorts.Apply(Filter(query), query.Sort).Take(50_000).Select(ToDto).ToListAsync(ct);
        return Csv.Write(rows,
            ("Fecha (UTC)", r => r.CreatedAt),
            ("Tipo", r => r.Type.ToString()),
            ("SKU", r => r.Sku),
            ("Producto", r => r.ProductName),
            ("Depósito", r => r.WarehouseCode),
            ("Cantidad", r => r.Quantity),
            ("Saldo", r => r.BalanceAfter),
            ("Motivo", r => r.Reason),
            ("Referencia", r => r.Reference),
            ("Proveedor", r => r.SupplierName),
            ("Usuario", r => r.UserName));
    }

    public async Task<IReadOnlyList<StockMovementDto>> RegisterAsync(StockMovementRequest request, CancellationToken ct)
    {
        var product = await GetActiveProductAsync(request.ProductId, ct);
        var warehouse = await GetActiveWarehouseAsync(request.WarehouseId, ct);
        if (request.SupplierId is not null && !await db.Suppliers.AnyAsync(s => s.Id == request.SupplierId, ct))
        {
            throw new NotFoundException("Proveedor", request.SupplierId);
        }

        var correlation = Guid.NewGuid();
        var movement = await db.InTransactionAsync(async () =>
        {
            var (type, delta) = request.Type switch
            {
                ManualMovementType.Entrada => (StockMovementType.Entrada, request.Quantity),
                ManualMovementType.Salida => (StockMovementType.Salida, -request.Quantity),
                ManualMovementType.Ajuste => (StockMovementType.Ajuste,
                    request.Quantity - await store.LockAsync(product.Id, warehouse.Id, ct)),
                _ => throw new DomainException("stock.type", "Tipo de movimiento inválido."),
            };

            if (delta == 0)
            {
                throw new DomainException("stock.no_change", "El stock contado coincide con el registrado: no hay nada para ajustar.");
            }

            var recorded = await ApplyAsync(product, warehouse, delta, type, correlation, request.Reason, request.Reference,
                invoiceId: null, request.SupplierId, ct);
            await db.SaveChangesAsync(ct);
            return recorded;
        }, ct);

        return await LoadAsync(movement.CorrelationId, ct);
    }

    public async Task<IReadOnlyList<StockMovementDto>> TransferAsync(StockTransferRequest request, CancellationToken ct)
    {
        var product = await GetActiveProductAsync(request.ProductId, ct);
        var from = await GetActiveWarehouseAsync(request.FromWarehouseId, ct);
        var to = await GetActiveWarehouseAsync(request.ToWarehouseId, ct);
        var correlation = Guid.NewGuid();
        var reference = $"{from.Code} → {to.Code}";

        await db.InTransactionAsync(async () =>
        {
            // Lock rows in a deterministic order (by warehouse id) to avoid deadlocks between opposite transfers.
            foreach (var w in new[] { from, to }.OrderBy(w => w.Id))
            {
                await store.LockAsync(product.Id, w.Id, ct);
            }

            await ApplyAsync(product, from, -request.Quantity, StockMovementType.Transferencia, correlation, request.Reason, reference, null, null, ct);
            await ApplyAsync(product, to, request.Quantity, StockMovementType.Transferencia, correlation, request.Reason, reference, null, null, ct);
            await db.SaveChangesAsync(ct);
            return true;
        }, ct);

        return await LoadAsync(correlation, ct);
    }

    /// <summary>
    /// Takes the invoiced goods out of the invoice warehouse. Called by the invoice workflow inside its
    /// transaction; any shortage throws and rolls back the whole issue (number included).
    /// </summary>
    internal async Task DispatchInvoiceAsync(Invoice invoice, Warehouse warehouse, CancellationToken ct)
    {
        var products = await LoadProductsAsync(invoice, ct);
        var correlation = Guid.NewGuid();
        // Same product in several lines → one movement. Ordered by id so concurrent invoices lock rows in the same order.
        foreach (var group in invoice.Lines.GroupBy(l => l.ProductId).OrderBy(g => g.Key))
        {
            await ApplyAsync(products[group.Key], warehouse, -group.Sum(l => l.Quantity), StockMovementType.Venta, correlation,
                "Venta", invoice.FormattedNumber, invoice.Id, null, ct);
        }
    }

    /// <summary>Returns the goods of a cancelled invoice to the warehouse they left from.</summary>
    internal async Task RestockCancelledInvoiceAsync(Invoice invoice, Warehouse warehouse, CancellationToken ct)
    {
        var products = await LoadProductsAsync(invoice, ct);
        var correlation = Guid.NewGuid();
        foreach (var group in invoice.Lines.GroupBy(l => l.ProductId).OrderBy(g => g.Key))
        {
            await ApplyAsync(products[group.Key], warehouse, group.Sum(l => l.Quantity), StockMovementType.AnulacionVenta, correlation,
                invoice.CancellationReason, invoice.FormattedNumber, invoice.Id, null, ct);
        }
    }

    private async Task<StockMovement> ApplyAsync(
        Product product, Warehouse warehouse, int delta, StockMovementType type, Guid correlation,
        string? reason, string? reference, int? invoiceId, int? supplierId, CancellationToken ct)
    {
        var change = await store.TryApplyAsync(product.Id, warehouse.Id, delta, ct);
        if (!change.Success)
        {
            throw new InsufficientStockException(product.Sku, warehouse.Name, -delta, change.Balance);
        }

        var movement = StockMovement.Record(
            product.Id, warehouse.Id, type, delta, change.Balance, currentUser.UserId, correlation, clock.UtcNow,
            reason, reference, invoiceId, supplierId);
        db.StockMovements.Add(movement);
        return movement;
    }

    private async Task<Dictionary<int, Product>> LoadProductsAsync(Invoice invoice, CancellationToken ct)
    {
        var ids = invoice.Lines.Select(l => l.ProductId).Distinct().ToList();
        return await db.Products.Where(p => ids.Contains(p.Id)).ToDictionaryAsync(p => p.Id, ct);
    }

    private async Task<IReadOnlyList<StockMovementDto>> LoadAsync(Guid correlation, CancellationToken ct) =>
        await db.StockMovements.AsNoTracking().Where(m => m.CorrelationId == correlation).OrderBy(m => m.Id).Select(ToDto).ToListAsync(ct);

    private async Task<Product> GetActiveProductAsync(int id, CancellationToken ct)
    {
        var product = await db.Products.AsNoTracking().SingleOrDefaultAsync(p => p.Id == id, ct) ?? throw new NotFoundException("Producto", id);
        return product.IsActive ? product : throw new DomainException("product.inactive", $"El producto {product.Sku} está inactivo.");
    }

    private async Task<Warehouse> GetActiveWarehouseAsync(int id, CancellationToken ct)
    {
        var warehouse = await db.Warehouses.AsNoTracking().SingleOrDefaultAsync(w => w.Id == id, ct) ?? throw new NotFoundException("Depósito", id);
        return warehouse.IsActive ? warehouse : throw new DomainException("warehouse.inactive", $"El depósito {warehouse.Code} está inactivo.");
    }

    private IQueryable<StockMovement> Filter(StockMovementQuery query)
    {
        var movements = db.StockMovements.AsNoTracking();
        if (query.ProductId is not null)
        {
            movements = movements.Where(m => m.ProductId == query.ProductId);
        }

        if (query.WarehouseId is not null)
        {
            movements = movements.Where(m => m.WarehouseId == query.WarehouseId);
        }

        if (query.Type is not null)
        {
            movements = movements.Where(m => m.Type == query.Type);
        }

        if (query.From is not null)
        {
            var from = query.From.Value.ToDateTime(TimeOnly.MinValue);
            movements = movements.Where(m => m.CreatedAt >= from);
        }

        if (query.To is not null)
        {
            var to = query.To.Value.AddDays(1).ToDateTime(TimeOnly.MinValue);
            movements = movements.Where(m => m.CreatedAt < to);
        }

        if (!string.IsNullOrWhiteSpace(query.Search))
        {
            var term = query.Search.Trim();
            movements = movements.Where(m => m.Product.Name.Contains(term) || m.Product.Sku.Contains(term) || (m.Reference != null && m.Reference.Contains(term)));
        }

        return movements;
    }
}
